// ── Normaliza payload e RETORNA CADA SEGMENTO COMO UM ITEM SEPARADO NO N8N ──
const body = $input.item.json.body || $input.item.json;
const tpl  = body.template || {};

const sessionId    = `dt_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
const captionStyle = tpl.caption_style || 'pop';
const animationMix = tpl.animation_mix || 'varied';
const language     = tpl.language     || 'pt';
const format       = tpl.format       || 'vertical';

// ── Normalização de Voz (mapeia categorias do Gemini para vozes Edge-TTS válidas) ──
function getValidEdgeVoice(rawVoice, lang) {
  if (!rawVoice) return lang === 'en' ? 'en-US-ChristopherNeural' : 'pt-BR-FranciscaNeural';
  const str = String(rawVoice).trim();
  const lower = str.toLowerCase();
  if (lower.includes('neural') || lower.includes('pt-br-') || lower.includes('en-us-')) {
    return str;
  }
  const map = {
    'masculine_br': 'pt-BR-AntonioNeural',
    'masculine-br': 'pt-BR-AntonioNeural',
    'masculino_br': 'pt-BR-AntonioNeural',
    'homem_br':     'pt-BR-AntonioNeural',
    'narrator':     'pt-BR-AntonioNeural',
    'feminine_br':  'pt-BR-FranciscaNeural',
    'feminine-br':  'pt-BR-FranciscaNeural',
    'feminino_br':  'pt-BR-FranciscaNeural',
    'mulher_br':    'pt-BR-FranciscaNeural',
    'masculine_en': 'en-US-ChristopherNeural',
    'feminine_en':  'en-US-AvaNeural'
  };
  return map[lower] || (lang === 'en' ? 'en-US-ChristopherNeural' : 'pt-BR-FranciscaNeural');
}

const voice = getValidEdgeVoice(tpl.voice || tpl.voice_model || body.voice, language);

// Engine inicial (será sobrescrito pelo AI Engine Selector)
const renderEngine = 'pending_ai_selection';

const userMedia = tpl.user_media || tpl.uploaded_images || tpl.images || [];
const hasUserMedia = Array.isArray(userMedia) && userMedia.length > 0;

const rawSegments = tpl.script_segments || body.script_segments || [];
let segments = rawSegments.length > 0 ? rawSegments : [{
  index: 0,
  voiceover: { text: tpl.video_title || 'Vídeo sem narração' },
  visual_content: { image_prompt: tpl.video_title || 'Cena principal' }
}];

if (hasUserMedia && userMedia.length < segments.length) {
  segments = segments.slice(0, userMedia.length);
}

return segments.map((seg, idx) => ({
  json: {
    ...seg,
    index: seg.index !== undefined ? seg.index : idx,
    session_id:     sessionId,
    render_engine:  renderEngine,
    caption_style:  captionStyle,
    animation_mix:  animationMix,
    language,
    voice,
    format,
    has_music:      tpl.has_music      || false,
    primary_color:  tpl.primary_color  || '#EAB308',
    accent_color:   tpl.accent_color   || '#FFFFFF',
    watermark_text: tpl.watermark_text || 'DarkTube AI',
    topic:          tpl.video_title    || '',
    emotion:        seg.emotion        || 'neutral',
    user_media:     userMedia,
    tpl
  }
}));

// Seleciona Imagem da Cena - estritamente 1-para-1 com a imagem enviada
const norm        = $json;
const idx         = parseInt(norm.index !== undefined ? norm.index : 0);
const tpl         = norm.tpl || {};
const visual      = norm.visual_content || {};

const userMedia   = norm.user_media || tpl.user_media || tpl.uploaded_images || tpl.images || [];

let providedUrl = norm.image_url
  || norm.media_url
  || visual.image_url
  || (Array.isArray(userMedia) && userMedia[idx] ? (userMedia[idx].file_url || userMedia[idx]) : '')
  || '';

let imageUrl = providedUrl || tpl.video_thumbnail || '';
let source   = providedUrl ? 'user_uploaded_image' : 'template_thumbnail';

return [{ json: { ...norm, image_url: imageUrl, source } }];

// ── Monta SceneSegment completo ──
const segment = $('Generate Scene Image').item.json;
const idx     = parseInt(segment.index !== undefined ? segment.index : 0);
const ttsNode = $('Generate TTS');
const ttsItem = ttsNode.item || (ttsNode.all() && ttsNode.all()[0]) || {};
const wRes    = $('Whisper Word Timestamps').item.json;

const voiceover = segment.voiceover || {};
const visual    = segment.visual_content || {};

const imageUrl = segment.image_url || segment.media_url || visual.image_url || segment.tpl?.video_thumbnail || '';

let audioUrl = segment.audio_url || '';
if (!audioUrl) {
  let base64Data = '';
  try {
    const getHelper = (typeof this !== 'undefined' && this.helpers && this.helpers.getBinaryDataBuffer) || (typeof $helpers !== 'undefined' && $helpers.getBinaryDataBuffer);
    if (getHelper) {
      const buf = await getHelper.call(this, 0, 'data', 'Generate TTS');
      if (buf && buf.length > 0) { base64Data = buf.toString('base64'); }
    }
  } catch (err) { console.error('Error fetching TTS binary buffer:', err.message); }

  if (!base64Data && ttsItem && ttsItem.binary) {
    const binaryKey = Object.keys(ttsItem.binary)[0] || 'data';
    const binaryObj = ttsItem.binary[binaryKey];
    if (binaryObj && binaryObj.data && binaryObj.data !== 'database') { base64Data = binaryObj.data; }
  }

  if (base64Data) { audioUrl = `data:audio/mp3;base64,${base64Data}`; }
}

const captionText = voiceover.text || segment.voiceover_text || segment.voiceoverText || segment.text || '';

const words = (wRes.words || wRes.segments?.[0]?.words || []).map(w => ({
  word: w.word,
  startInSeconds: parseFloat(w.start),
  endInSeconds:   parseFloat(w.end)
}));

const duration = wRes.duration || (() => {
  const ts = segment.timestamp || '';
  const parts = ts.split('-');
  const toSec = t => { const p = t.trim().split(':'); return p.length===2 ? parseInt(p[0])*60+parseInt(p[1]) : parseInt(p[0]); };
  return parts.length === 2 ? toSec(parts[1]) - toSec(parts[0]) : 5;
})();

const ALL_STYLES = ['kenburns-right','kenburns-left','zoom-punch','parallax-up','zoom-out'];
let animationStyle;
if (segment.animation_mix === 'kenburns')         animationStyle = idx % 2 === 0 ? 'kenburns-right' : 'kenburns-left';
else if (segment.animation_mix === 'zoom-punch')  animationStyle = 'zoom-punch';
else animationStyle = ALL_STYLES[idx % ALL_STYLES.length];

return [{
  json: {
    index:          idx,
    imageUrl,
    audioUrl,
    captionText,
    words,
    durationSeconds: duration,
    animationStyle,
    transitionIn:   'fade',
    emotion:        segment.emotion || 'neutral'
  }
}];

// ── Agrega todas as cenas geradas pelo loop ──
const norm = $('Normalize + Auto Engine').first().json;
const tpl  = norm.tpl || {};

const scenes = $input.all()
  .map(item => item.json)
  .sort((a, b) => a.index - b.index);

const execId = $execution?.id || '';
const resumeUrl = $execution?.resumeUrl || '';
const baseCallback = resumeUrl || (execId ? `https://n8n.fjt-solutions.com/webhook-waiting/${execId}/darktube-render-complete` : `https://n8n.fjt-solutions.com/webhook-waiting/darktube-render-complete`);

const composition = {
  scenes,
  format:            norm.format,
  captionStyle:      norm.caption_style,
  primaryColor:      norm.primary_color,
  accentColor:       norm.accent_color,
  showWatermark:     false,
  watermarkText:     norm.watermark_text,
  backgroundMusicUrl: norm.has_music ? (tpl.music_url || '') : ''
};

return [{
  json: {
    session_id:    norm.session_id,
    render_engine: norm.render_engine,
    template_id:   tpl.id,
    callback_url:  baseCallback,
    topic:         norm.topic         || tpl.video_title || '',
    emotion:       scenes[0]?.emotion || 'neutral',
    composition
  }
}];

// ══════════════════════════════════════════════════════════════
// AI ENGINE SELECTOR — Prepara o prompt para o AI Agent OpenAI
// ══════════════════════════════════════════════════════════════
const comp   = $json.composition || {};
const scenes = comp.scenes || [];

const topic        = $json.topic        || comp.topic        || 'não informado';
const emotion      = $json.emotion      || scenes[0]?.emotion || 'neutral';
const captionStyle = comp.captionStyle  || 'subtitle';
const sceneCount   = scenes.length;
const totalDur     = scenes.reduce((s, c) => s + (c.durationSeconds || 5), 0);
const hasImages    = scenes.some(s => s.imageUrl) ? 'sim' : 'não';
const firstWords   = scenes.slice(0, 3).map(s => s.captionText || '').join(' | ');

const userMessage = `Analise este vídeo e escolha o engine de renderização:

- Tema: ${topic}
- Emoção predominante: ${emotion}
- Estilo de legenda configurado: ${captionStyle}
- Número de cenas: ${sceneCount}
- Duração total: ${totalDur.toFixed(1)}s
- Tem imagens de fundo: ${hasImages}
- Primeiras legendas: ${firstWords}

Responda APENAS com JSON puro (sem markdown): {"engine":"hyperframes","reason":"motivo curto"}`;

return [{ json: { ...$json, _selectorPrompt: userMessage } }];

// ══════════════════════════════════════════════════════════════
// ENGINE SELECTOR — Extrai resultado do AI Agent
// ══════════════════════════════════════════════════════════════
const output = $json.output || $json.text || $json.message?.content || '';

let parsed = { engine: 'hyperframes', reason: 'fallback padrão' };
try {
  const clean = output.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(clean);
} catch {
  parsed = {
    engine: output.toLowerCase().includes('remotion') ? 'remotion' : 'hyperframes',
    reason: 'detectado por keyword'
  };
}

const original = $('Engine Selector — Prepara').first().json;
return [{
  json: {
    ...original,
    render_engine: parsed.engine || 'hyperframes',
    engineReason:  parsed.reason || '',
  }
}];

// ══════════════════════════════════════════════════════════════
// AI DIRECTOR REMOTION — Prepara prompt de direção cinematográfica
// ══════════════════════════════════════════════════════════════
const comp   = $json.composition || {};
const scenes = comp.scenes || [];
const emotion = $json.emotion || scenes[0]?.emotion || 'neutral';
const style   = comp.captionStyle || 'pop';
const topic   = $json.topic || '';

const userMessage = `Crie a direção cinematográfica para este vídeo Remotion.

Estilo de legenda: ${style}
Emoção geral: ${emotion}
Tema: ${topic}

Cenas:
${JSON.stringify(scenes.map(s => ({ index: s.index, captionText: s.captionText, durationSeconds: s.durationSeconds, emotion: s.emotion })), null, 2)}

Responda APENAS com JSON array (sem markdown):
[{"index":0,"transitionIn":"slide-right","transitionDurationFrames":18,"textEffect":"pop","springPreset":"bouncy","intensity":0.8,"emotionColor":"#FF6B35"}]`;

return [{ json: { ...$json, _directorPrompt: userMessage } }];

// ══════════════════════════════════════════════════════════════
// AI DIRECTOR REMOTION — Aplica direção ao payload
// ══════════════════════════════════════════════════════════════
const output = $json.output || $json.text || $json.message?.content || '[]';

let directions = [];
try {
  const clean = output.replace(/```json/g, '').replace(/```/g, '').trim();
  const match = clean.match(/\[.*\]/s);
  directions = JSON.parse(match ? match[0] : clean);
} catch (e) {
  console.log('Director Remotion parse error:', e.message);
  directions = [];
}

const original = $('Director Remotion — Prepara').first().json;
const comp = original.composition || {};
const scenes = comp.scenes || [];

const enriched = scenes.map(scene => {
  const dir = directions.find(d => d.index === scene.index) || {};
  return {
    ...scene,
    transitionIn:             dir.transitionIn             || scene.transitionIn || 'fade',
    transitionDurationFrames: dir.transitionDurationFrames || 18,
    textEffect:               dir.textEffect               || 'pop',
    springPreset:             dir.springPreset             || 'bouncy',
    intensity:                dir.intensity                ?? 0.8,
    emotionColor:             dir.emotionColor             || null,
  };
});

return [{
  json: {
    ...original,
    composition: { ...comp, scenes: enriched },
    _directorApplied: 'remotion',
  }
}];

// ══════════════════════════════════════════════════════════════
// AI DIRECTOR HYPERFRAMES — Prepara prompt de direção cinematográfica
// ══════════════════════════════════════════════════════════════
const comp   = $json.composition || {};
const scenes = comp.scenes || [];
const emotion = $json.emotion || scenes[0]?.emotion || 'neutral';
const style   = comp.captionStyle || 'subtitle';
const topic   = $json.topic || '';

const userMessage = `Crie a direção cinematográfica para este vídeo HyperFrames.

Estilo de legenda: ${style}
Emoção geral: ${emotion}
Tema: ${topic}

Cenas:
${JSON.stringify(scenes.map(s => ({ index: s.index, captionText: s.captionText, durationSeconds: s.durationSeconds, hasImage: !!s.imageUrl, emotion: s.emotion })), null, 2)}

Responda APENAS com JSON array (sem markdown):
[{"index":0,"animationStyle":"kenburns-right","transitionIn":"light-leak","captionEffect":"bounce","intensity":0.8}]`;

return [{ json: { ...$json, _directorPrompt: userMessage } }];

// ══════════════════════════════════════════════════════════════
// AI DIRECTOR HYPERFRAMES — Aplica direção ao payload
// ══════════════════════════════════════════════════════════════
const output = $json.output || $json.text || $json.message?.content || '[]';

let directions = [];
try {
  const clean = output.replace(/```json/g, '').replace(/```/g, '').trim();
  const match = clean.match(/\[.*\]/s);
  directions = JSON.parse(match ? match[0] : clean);
} catch (e) {
  console.log('Director HyperFrames parse error:', e.message);
  directions = [];
}

const original = $('Director HyperFrames — Prepara').first().json;
const comp = original.composition || {};
const scenes = comp.scenes || [];

const enriched = scenes.map(scene => {
  const dir = directions.find(d => d.index === scene.index) || {};
  return {
    ...scene,
    animationStyle: dir.animationStyle || scene.animationStyle || 'kenburns-right',
    transitionIn:   dir.transitionIn   || scene.transitionIn   || 'fade',
    captionEffect:  dir.captionEffect  || 'bounce',
    intensity:      dir.intensity      ?? 0.75,
  };
});

return [{
  json: {
    ...original,
    composition: { ...comp, scenes: enriched },
    _directorApplied: 'hyperframes',
  }
}];

// ── Auto-Post Blotato (Publicação Social) ──
const norm = $('Normalize + Auto Engine').first().json;
const tpl  = norm.tpl || {};
const waitRes = $('Wait Render').first().json;

const accounts = tpl.target_accounts || [];
if (accounts.length === 0) {
  return [{ json: { status: 'skipped_no_accounts', video_url: waitRes.video_url || waitRes.videoUrl || '' } }];
}

return [{ json: { status: 'ready_to_post', accounts, video_url: waitRes.video_url || waitRes.videoUrl || '' } }];

